import React, { FC } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import LoadingBallancer from '@commons/loading-router';
import { ROUTER_PATH } from '@utils/router';
import AppErrorPopup from '@commons/error-popup';
import './scss/app.scss';

const HomeScreen = React.lazy(() => import('@screens/home.screen'));
const ContactScreen = React.lazy(() => import('@screens/contact.screen'));
const GuideLineScreen = React.lazy(() => import('@screens/guidelines.screen'));
const PageNotFound = React.lazy(() => import('@screens/404.screen'));

interface AppProps {
	children?: React.ReactNode;
}

export const queryClient = new QueryClient({
	defaultOptions: {
		queries: {
			retry: false,
			refetchOnWindowFocus: false
		}
	}
});

const App: FC<AppProps> = () => {
	console.log('environment', process.env.REACT_APP_DOMAIN_API);
	return (
		<QueryClientProvider client={queryClient}>
			<React.Suspense fallback={<LoadingBallancer />}>
				<BrowserRouter>
					<Routes>
						<Route path={ROUTER_PATH.HOME} element={<HomeScreen />} />
						<Route path={ROUTER_PATH.CONTACT} element={<ContactScreen />} />
						<Route path={ROUTER_PATH.GUIDELINE} element={<GuideLineScreen />} />
						<Route path={ROUTER_PATH.PAGENOTFOUND} element={<PageNotFound />} />
					</Routes>
				</BrowserRouter>
			</React.Suspense>
			<AppErrorPopup />
		</QueryClientProvider>
	);
};

export default React.memo(App);
