import * as React from 'react';
import { createTheme, ThemeProvider, ThemeOptions, Theme } from '@mui/material/styles';

import { lightTheme, darkTheme, themeExtensions } from './theme.config';

interface IMuiThemeApp {
  children: React.ReactNode;
}

export default function MuiThemeApp({ children }: IMuiThemeApp) {
  const [isDarkMode, setIsDarkMode] = React.useState(false);

  // Toggle theme mode
  const handleThemeChange = () => {
    setIsDarkMode(prevMode => !prevMode);
  };

  const extendTheme = (
    baseTheme: Theme, customizations: ThemeOptions): Theme => createTheme(baseTheme, customizations);

  const extendedLightTheme = React.useMemo(
    () => extendTheme(lightTheme, themeExtensions),
  []);
  
  const extendedDarkTheme = React.useMemo(
    () => extendTheme(darkTheme, themeExtensions),
  []);

  return (
    <ThemeProvider theme={isDarkMode ? extendedDarkTheme : extendedLightTheme}>
      {children}
    </ThemeProvider>
  );
}