import React from "react";
import { Modal } from "antd";
import { useSelector } from "react-redux";
import { AppState } from "@redux/reducers";
import { useDispatch } from "react-redux";
import { handleSetErrorApi } from "@redux/actions/app.action";
import { useTranslation } from "react-i18next";
import { AppButton } from "@shared/form/button";

const AppErrorPopup = () => {
  const dispatch = useDispatch();
  const { t } = useTranslation();
  const appError = useSelector((state: AppState) => state.appCommon.error);

  const onOK = () => {
    closeErrorModal();
  }

  const closeErrorModal = React.useCallback(() => {
    dispatch(handleSetErrorApi({
      isShow: false,
      errorCode: null,
      errorMsg: '',
      content: null
    }))
  }, [dispatch]);

  return (
    <Modal
      title="Oops!"
      style={{ top: 20 }}
      open={appError?.isShow || false}
      onCancel={closeErrorModal}
      footer={
        <AppButton
          color='error'
          variant="contained"
          size="small"
          text={t('common.button.ok')}
          onClick={onOK}
        />
      }
    >
      <p>{appError?.errorMsg}</p>
    </Modal>
  );
}

export default React.memo(AppErrorPopup)