import { all, put, takeLatest } from "redux-saga/effects";

import { loadUsersAsync } from "@actions/user.action";
import apiService from "@services/index";
import { AxiosResponse } from "axios";
import { User } from "@appTypes/user";

function* userSaga() {
  yield all([takeLatest(loadUsersAsync.request, loadUsersSaga)]);
}


function* loadUsersSaga(
  action: ReturnType<typeof loadUsersAsync.request>
): Generator<any, void, AxiosResponse<User[]>> {
  try {
    const data = action.payload;
    const response: AxiosResponse<User[]> = yield apiService.get('', {
      params: data
    });
    const users: User[] = response?.data;
    
    yield put(
      loadUsersAsync.success(users)
    );
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : 'An unknown error occurred';
    yield put(
      loadUsersAsync.failure(errorMessage)
    );
  }
}

export default userSaga;
