import axios, { AxiosRequestConfig } from 'axios';
import { store } from '@redux/index';
import { STATUS_CODES } from '@utils/api.path';
import { handleSetErrorApi } from '@redux/actions/app.action';

const DOMAIN_API = process.env.REACT_APP_DOMAIN_API;
const PREFIX_API = process.env.REACT_APP_PREFIX_API;

export const AxiosInstance = axios.create({
  baseURL: `${DOMAIN_API}${PREFIX_API}`,
  timeout: 100000,
  withCredentials: true,
});

AxiosInstance.interceptors.request.use((request: AxiosRequestConfig) => {
  if (!request.headers) return;

  // request.headers['x-rapidapi-host'] = 'etsy-product.p.rapidapi.com';
  // request.headers['x-rapidapi-key'] = '7f343e866amsh291afe5aa351b75p1ca9a5jsn27f05f3901f4';

  const token = localStorage.getItem('ACCESS-TOKEN');
  if (token) {
    request.headers['Authorization'] = `Bearer ${token}`;
  }

  return request;
}, (error) => {
  return Promise.reject(error);
});

AxiosInstance.interceptors.response.use(
  (response) => response,
  (error) => {
    // handle error
    const { response } = error;
    if (!response) return Promise.reject(error);

    const errorStatus = response?.status;
    switch (errorStatus) {
      case STATUS_CODES.UNAUTHORIZED:
      case STATUS_CODES.FORBIDDEN:
        localStorage.removeItem('ACCESS-TOKEN');
        break;
      case STATUS_CODES.TOO_MANY_REQUESTS:
        store.dispatch(handleSetErrorApi({
          isShow: true,
          errorCode: errorStatus,
          errorMsg: response?.data?.message,
          content: ''
        }));
        break;
      default:
        break;
    }

    store.dispatch(handleSetErrorApi({
      isShow: true,
      errorCode: errorStatus,
      errorMsg: response?.data?.message,
      content: ''
    }));
    return Promise.reject(response);
  });

const APIService = {
  get<T>(uri: string, moreConfigs: AxiosRequestConfig<T> = {}): Promise<T> {
    return AxiosInstance.get(uri, moreConfigs).then((resp) => resp?.data)
      .catch((err) => {
        return Promise.reject(err);
      });
  },

  post<T>(uri: string, data = {}, moreConfigs: AxiosRequestConfig = {}): Promise<T> {
    return AxiosInstance.post(uri, data, moreConfigs)
      .then((resp) => resp?.data)
      .catch((err) => {
        return Promise.reject(err);
      });
  },

  put<T>(uri: string, data = {}, moreConfigs: AxiosRequestConfig = {}): Promise<T> {
    return AxiosInstance.put<T>(uri, data, moreConfigs)
      .then((resp) => resp?.data)
      .catch((err) => {
        return Promise.reject(err);
      });
  },

  delete<T>(uri: string, moreConfigs: AxiosRequestConfig = {}): Promise<T> {
    return AxiosInstance.delete<T>(uri, moreConfigs)
      .then((resp) => resp?.data)
      .catch((err) => {
        return Promise.reject(err);
      });
  },

  patch<T>(uri: string, data = {}, moreConfigs: AxiosRequestConfig = {}): Promise<T> {
    return AxiosInstance.patch<T>(uri, data, moreConfigs)
      .then((resp) => resp?.data)
      .catch((err) => {
        return Promise.reject(err);
      });
  }
}

export default APIService;
