import { createReducer } from "typesafe-actions";

import { ActionDispatcherType, IAppErrorApi } from "@appTypes/app";
import { handleSetErrorApi } from "@actions/app.action";

export interface IAppState {
  error: IAppErrorApi
}

const initialApp: IAppState = {
  error: {
    isShow: false,
    errorCode: null,
    errorMsg: '',
    content: null,
  }
}

const AppReducer = createReducer<IAppState>(initialApp)
  .handleAction(handleSetErrorApi,
    (state: IAppState, action: ActionDispatcherType<IAppErrorApi>) => {
      console.log("action handleSetErrorApi", action);
      return {
        ...state,
        error: action.payload
      }
    }
  )

export default AppReducer;
