import { createReducer } from "typesafe-actions";

import { User } from "@appTypes/user";
import { ActionDispatcherType } from "@appTypes/app";
import { loadUsersAsync } from "@actions/user.action";

export type IUserState = {
	profile: {
		id: string | number;
	};
};

const initialUser: IUserState = {
  profile: {
    id: ""
  }
}

const UserReducer = createReducer<IUserState>(initialUser)
  .handleAction(
    loadUsersAsync.success,
    (state: IUserState, action: ActionDispatcherType<User[]>) => {
      console.log("action", action);

      return {
        ...state,

      }
    }
  );

export default UserReducer;
